package offline;


/** Canonical frame model: preserves type, order, optional flags and opaque payload bytes. */
final class Frame {
    static final byte[] NO_BYTES = new byte[0];
    static final long[] NO_LONGS = new long[0];

    /** Frame type value. */
    long type;
    /** Body varints, meaning depends on the type. */
    long v1;
    long v2;
    long v3;
    /** ECN counters of an ACK_ECN frame. */
    long e0;
    long e1;
    long e2;
    /** ACK (gap, range) pairs in wire order. */
    long[] pairs = NO_LONGS;
